<?php include 'header.php';if(isset($_POST['save'])){$st=$pdo->prepare('INSERT INTO notices(title,body,status) VALUES(?,?,?)');$st->execute([trim($_POST['title']),trim($_POST['body']),isset($_POST['status'])?1:0]);header('Location:notices.php');exit;}if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM notices WHERE id=?')->execute([(int)$_GET['delete']]);header('Location:notices.php');exit;}$rows=$pdo->query('SELECT * FROM notices ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);?><h1>নোটিশ বোর্ড</h1><div class="panel"><form method="post"><input name="title" placeholder="নোটিশের শিরোনাম" required><textarea name="body" placeholder="বিস্তারিত লিখুন"></textarea><label><input type="checkbox" name="status" checked> প্রকাশিত</label><button name="save">নোটিশ প্রকাশ করুন</button></form></div><div class="panel"><table><tr><th>শিরোনাম</th><th>তারিখ</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['title'])?></td><td><?=htmlspecialchars($r['published_at'])?></td><td><a class="danger" href="?delete=<?=$r['id']?>" onclick="return confirm('Delete?')">Delete</a></td></tr><?php endforeach;?></table></div><?php include 'footer.php';?>